package com.bank.rotatedmin;

import java.math.BigDecimal;
import java.util.logging.Logger;

// Finds the lowest rate in a rotated checkpoint list for National Bank of India.
public class RotatedArraySearch {
    private static final Logger log = Logger.getLogger(RotatedArraySearch.class.getName());

    // Minimum of a rotated sorted array (distinct values). O(log n), O(1).
    public BigDecimal findMinimumRate(BigDecimal[] rates) {
        if (rates == null || rates.length == 0) {
            throw new IllegalArgumentException("rates must be non-empty");
        }
        int lo = 0;
        int hi = rates.length - 1;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;                   // safe midpoint
            if (rates[mid].compareTo(rates[hi]) > 0) {
                lo = mid + 1;                            // pivot is to the right
            } else {
                hi = mid;                                // min is at mid or left
            }
        }
        final BigDecimal result = rates[lo];
        log.info(() -> "Minimum rate at index " + lo + " = " + result);
        return rates[lo];
    }
}
