package com.bank.rotatedmin;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: lowest rate in a rotated checkpoint list.
public class RotatedMinDemo {
    private static final Logger log = Logger.getLogger(RotatedMinDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    private static BigDecimal bd(String s) { return new BigDecimal(s); }

    public static void main(String[] args) {
        RotatedArraySearch search = new RotatedArraySearch();

        // Rotated ascending interest-rate checkpoints (%).
        BigDecimal[] rotated = { bd("4"), bd("5"), bd("6"), bd("7"), bd("0"), bd("1"), bd("2") };
        BigDecimal min = search.findMinimumRate(rotated);
        log.info(() -> "Lowest rate (rotated) = " + min);

        // Zero-rotation case: already sorted.
        BigDecimal[] sorted = { bd("1"), bd("2"), bd("3"), bd("4") };
        log.info(() -> "Lowest rate (no rotation) = " + search.findMinimumRate(sorted));
    }
}
